-- 兑换码兑换回滚脚本（MQ 发送失败时调用）
-- KEYS[1]: coupon:code:map (Bitmap)
-- KEYS[2]: prs:user:coupon:{couponId} (用户领取计数)
-- KEYS[3]: prs:coupon:{couponId} (优惠券缓存)
-- ARGV[1]: serialNum
-- ARGV[2]: userId
--
-- 返回值: 1-无需回滚(用户计数已为0) 0-回滚成功

-- 1. 回滚 Bitmap 防重标记
redis.call('SETBIT', KEYS[1], ARGV[1], 0)

-- 2. 防御：仅当用户计数 > 0 时才回滚，防止重复回滚导致计数为负
local cur = tonumber(redis.call('HGET', KEYS[2], ARGV[2]) or "0")
if cur <= 0 then
    return 1
end

-- 3. 回滚用户领取计数
redis.call('HINCRBY', KEYS[2], ARGV[2], -1)

-- 4. 回滚库存
redis.call('HINCRBY', KEYS[3], "totalNum", 1)

return 0